#!/usr/bin/env python3
from pwn import *
import re

# Create a remote connection
conn = remote('misc.chal.csaw.io', 3535)

# Function to parse cursor position from ANSI escape sequence
def parse_cursor_pos(cmd):
    # \u001b[<n>G moves cursor to column n
    if 'G' in cmd:
        return int(cmd.replace('G', ''))
    # \u001b[<n>d moves cursor to row n
    elif 'd' in cmd:
        return int(cmd.replace('d', ''))
    return None

# Dictionary to store characters at each position
position_chars = {}
current_pos = 1

# Read raw output and process it
output = conn.recvall()
# Convert to hex for better visualization
print("Raw output in hex:")
print(hexdump(output))

# Split by escape sequences
parts = output.split(b'\x1b[')

# Process each part
for part in parts:
    if not part:
        continue

    # Try to decode as UTF-8, ignore errors
    try:
        decoded = part.decode('utf-8', errors='ignore')
    except:
        continue

    # Look for cursor position commands
    match = re.match(r'(\d+[Gd])(.*)', decoded)
    if match:
        pos_cmd, text = match.groups()
        pos = parse_cursor_pos(pos_cmd)
        if pos is not None:
            if 'G' in pos_cmd:
                current_pos = pos
            # Store character at position
            if text.strip():
                position_chars[current_pos] = text.strip()[0]

# Sort positions and construct message
positions = sorted(position_chars.keys())
message = ''
for pos in positions:
    message += position_chars[pos]

print("\nReconstructed message:")
print(message)

