from pwn import *
import re

def main():
    # Create a remote connection
    conn = remote('misc.chal.csaw.io', 3535)

    # Dictionary to store characters at their positions
    char_positions = {}

    # Receive all data
    data = conn.recvall()

    # Split on ESC sequences
    parts = data.split(b'\x1b[')

    row = 1
    col = 1

    for part in parts:
        if not part:
            continue

        try:
            part_str = part.decode('utf-8', errors='ignore')

            # Handle row positioning (d)
            if 'd' in part_str:
                row_match = re.match(r'(\d+)d', part_str)
                if row_match:
                    row = int(row_match.group(1))

            # Handle column positioning (G)
            elif 'G' in part_str:
                col_match = re.match(r'(\d+)G(.*)', part_str)
                if col_match:
                    col = int(col_match.group(1))
                    content = col_match.group(2)
                    if content and not content.startswith('[') and not content.startswith('?'):
                        char_positions[(row, col)] = content[0]

            # Handle direct character output after cursor positioning
            elif part_str and not part_str.startswith('[') and not part_str.startswith('?'):
                char_positions[(row, col)] = part_str[0]

        except:
            continue

    # Sort positions by row and column
    sorted_positions = sorted(char_positions.items())

    # Extract message
    message = ''
    prev_row = None

    for (row, col), char in sorted_positions:
        if prev_row is not None and row != prev_row:
            message += '\n'
        message += char
        prev_row = row

    print("\nExtracted characters by position:")
    for pos, char in sorted_positions:
        print(f"Row {pos[0]}, Col {pos[1]}: {char}")

    print("\nPossible message:")
    print(message)

if __name__ == "__main__":
    main()

