    # Create a remote connection
    conn = remote('misc.chal.csaw.io', 3535)

    # Dictionary to store characters at their positions
    char_positions = {}

    # Receive data in chunks to capture everything
    all_data = b""
    try:
        while True:
            chunk = conn.recv(timeout=1)
            if not chunk:
                break
            all_data += chunk
    except:
        pass

    # Find all cursor movements and character placements
    cursor_moves = re.finditer(b'\x1b\\[(\\d+)([dG])([^\\x1b])?', all_data)

    current_row = 1
    for match in cursor_moves:
        num = int(match.group(1))
        cmd = match.group(2).decode()
        char = match.group(3).decode('utf-8', errors='ignore') if match.group(3) else None

        if cmd == 'd':
            current_row = num
        elif cmd == 'G' and char:
            if char.isprintable() and not char.isspace() and not char.startswith('['):
                char_positions[(current_row, num)] = char

    # Sort by row then column
    sorted_positions = sorted(char_positions.items())

    print("\nExtracted characters by position:")
    current_row = None
    message = ""

    for (row, col), char in sorted_positions:
        if current_row != row:
            if current_row is not None:
                print(f"\nRow {row}:", end=" ")
                message += "\n"
            else:
                print(f"Row {row}:", end=" ")
            current_row = row
        print(f"{char}", end="")
        message += char

    print("\n\nReconstructed message:")
    print(message)

