                        cmd = data[i:i+1].decode()
                        i += 1

                        if cmd == 'G':  # Set column
                            current_col = int(num) - 1 if num else 0
                        elif cmd == 'd':  # Set row
                            current_row = int(num) - 1 if num else 0

                        if i < len(data) and data[i:i+1] != b'\x1b':
                            char = data[i:i+1].decode('latin1')
                            if char.isprintable() and not char.isspace():
                                screen[current_row][current_col] = char
                            i += 1
