    char_positions = {}
    buffer = b""

    try:
        while True:
            try:
                chunk = conn.recv(4096, timeout=1)
                if not chunk:
                    break
                buffer += chunk

                # Process complete escape sequences
                cursor_pos = 1  # Keep track of horizontal cursor position
                row = 1        # Keep track of vertical cursor position

                i = 0
                while i < len(buffer):
                    if buffer[i:i+2] == b'\x1b[':
                        # Found escape sequence start
                        seq_end = i + 2
                        while seq_end < len(buffer) and buffer[seq_end:seq_end+1].decode('latin1') not in 'ABCDEFGHJKSTfmndsu':
                            seq_end += 1

                        if seq_end < len(buffer):
                            seq = buffer[i:seq_end+1]
                            match = re.match(b'\x1b\\[(\\d+)([dG])', seq)

                            if match:
                                num = int(match.group(1))
                                cmd = match.group(2).decode()

                                if cmd == 'G':
                                    cursor_pos = num
                                elif cmd == 'd':
                                    row = num

                                # Check if there's a character after the sequence
                                if seq_end + 1 < len(buffer):
                                    char = buffer[seq_end+1:seq_end+2].decode('latin1')
                                    if char.isprintable() and not char.isspace():
                                        char_positions[(row, cursor_pos)] = char

                            i = seq_end + 1
                        else:
                            break
                    else:
                        i += 1

                # Keep only unprocessed part
                buffer = buffer[i:]

            except EOFError:
                break
    except Exception as e:
        print(f"Error: {e}")
    finally:
        conn.close()

