from pwn import *
import time
import string
import re

def process_ansi(chunk):
    """Process ANSI escape sequences and extract cursor positions and characters."""
    positions = []
    chars = []
    i = 0
    current_x = 1
    current_y = 1

    while i < len(chunk):
        if chunk[i:i+2] == b'\x1b[':
            i += 2
            num = ''
            nums = []

            # Parse numbers in the sequence
            while i < len(chunk) and (chunk[i:i+1].isdigit() or chunk[i:i+1] == b';'):
                if chunk[i:i+1] == b';':
                    if num:
                        nums.append(int(num))
                        num = ''
                else:
                    num += chunk[i:i+1].decode()
                i += 1

            if num:
                nums.append(int(num))

            # Process the command
            if i < len(chunk):
                cmd = chunk[i:i+1].decode()
                if cmd == 'H' or cmd == 'f':  # Cursor position
                    if len(nums) >= 2:
                        current_y, current_x = nums
                    elif len(nums) == 1:
                        current_y = nums[0]
                        current_x = 1
                elif cmd == 'G':  # Cursor horizontal absolute
                    if nums:
                        current_x = nums[0]
                elif cmd == 'd':  # Cursor vertical absolute
                    if nums:
                        current_y = nums[0]
                i += 1
        else:
            # Regular character
            try:
                char = chunk[i:i+1].decode('ascii', errors='ignore')
                if char and char in string.printable and not char.isspace():
                    positions.append((current_x, current_y))
                    chars.append(char)
                    current_x += 1
            except:
                pass
            i += 1

    return positions, chars

def reconstruct_screen(positions, chars):
    """Reconstruct the screen contents from positions and characters."""
    screen = {}
    for pos, char in zip(positions, chars):
        screen[pos] = char
    return screen

def analyze_screen(screen):
    """Analyze the screen contents to find patterns."""
    # Sort positions by y then x
    sorted_pos = sorted(screen.keys(), key=lambda p: (p[1], p[0]))

    # Group characters by row
    rows = {}
    for pos in sorted_pos:
        y = pos[1]
        if y not in rows:
            rows[y] = []
        rows[y].append((pos[0], screen[pos]))

    # Sort each row and combine characters
    row_text = {}
    for y in sorted(rows.keys()):
        sorted_chars = [char for _, char in sorted(rows[y])]
        row_text[y] = ''.join(sorted_chars)

    return row_text

def main():
    all_positions = []
    all_chars = []

    conn = remote('misc.chal.csaw.io', 3535)
    try:
        start_time = time.time()
        while time.time() - start_time < 5:
            try:
                chunk = conn.recv(timeout=0.1)
                if not chunk:
                    continue

                positions, chars = process_ansi(chunk)
                all_positions.extend(positions)
                all_chars.extend(chars)

            except EOFError:
                break
    finally:
        conn.close()

    # Reconstruct and analyze the screen
    screen = reconstruct_screen(all_positions, all_chars)
    row_text = analyze_screen(screen)

    print("\nScreen contents by row:")
    for y in sorted(row_text.keys()):
        text = row_text[y]
        if text.strip():  # Only print non-empty rows
            print(f"Row {y:2d}: {text}")

    # Look for patterns that might be a password or flag
    all_text = ''.join(row_text.values())
    print("\nAnalyzing patterns:")

    # Look for sequences that might be passwords
