import re
import time

# Enable debug logging
context.log_level = 'debug'

def analyze_connection():
    # Connect to server
    r = remote('misc.chal.csaw.io', 3535)

    # Store timeline of events
    timeline = []
    cursor_pos = [1, 1]  # [row, col]
    screen = {}  # (row, col) -> (char, timestamp, attributes)

    # Track ANSI sequences
    ansi_re = re.compile(rb'\x1b\[([\d;]*)([A-Za-z])')

    start_time = time.time()

    try:
        while True:
            # Receive data with a timeout
            try:
                c = r.recv(1)
                if not c:
                    break

                current_time = time.time() - start_time

                # Check for escape sequence
                if c == b'\x1b':
                    seq = b'\x1b'
                    while True:
                        next_c = r.recv(1)
                        if not next_c:
                            break
                        seq += next_c
                        if next_c in b'ABCDEFGHJKSTfhlmnsu':
                            break

                    # Parse the sequence
                    match = ansi_re.match(seq)
                    if match:
                        params = match.group(1).decode('ascii')
                        command = match.group(2).decode('ascii')

                        # Log the sequence
                        timeline.append((current_time, 'sequence', seq, cursor_pos.copy()))

                        # Handle cursor positioning
                        if command in 'Hf':
                            if params:
                                row, col = map(int, params.split(';'))
                                cursor_pos = [row, col]
                        elif command == 'G':
                            if params:
                                cursor_pos[1] = int(params)
                        elif command == 'd':
                            if params:
                                cursor_pos[0] = int(params)

                # Regular character
                else:
                    char = c.decode('latin1')
                    timeline.append((current_time, 'char', char, cursor_pos.copy()))
                    screen[(cursor_pos[0], cursor_pos[1])] = (char, current_time, None)
                    cursor_pos[1] += 1

            except EOFError:
                break
            except Exception as e:
                timeline.append((current_time, 'error', str(e), cursor_pos.copy()))
                break

    finally:
        r.close()

    return timeline, screen

def analyze_patterns():
    # Collect data from multiple connections
    all_timelines = []
    all_screens = []

    for i in range(3):  # Make 3 connections to analyze patterns
        timeline, screen = analyze_connection()
        all_timelines.append(timeline)
        all_screens.append(screen)
        time.sleep(1)  # Wait between connections

    # Analyze patterns
    patterns = []
    hidden_text = []

    for timeline, screen in zip(all_timelines, all_screens):
        # Look for overwritten characters
        char_positions = {}
        for (row, col), (char, ts, attrs) in screen.items():
            if (row, col) not in char_positions:
                char_positions[(row, col)] = []
            char_positions[(row, col)].append((char, ts))

        # Find positions with multiple writes
        for pos, chars in char_positions.items():
            if len(chars) > 1:
                patterns.append(f"Position {pos} overwrites: {chars}")

