            patterns.append(f"Cursor movement pattern: {cursor_moves}")

        # Look for hidden text (chars visible for <0.1s)
        for i in range(len(timeline)-1):
            if timeline[i][1] == 'char':
                char_time = timeline[i][0]
                next_time = timeline[i+1][0]
                if next_time - char_time < 0.1:  # Brief visibility
                    hidden_text.append((timeline[i][2], timeline[i][3], char_time))

    return patterns, hidden_text

