    r = remote('misc.chal.csaw.io', 3535)

    # Track contents of line 8
    line8 = {}  # position -> list of (char, timestamp)
    current_pos = [1, 1]

    try:
        while True:
            try:
                c = r.recv(1)
                if not c:
                    break

                current_time = time.time()

                # Check for escape sequence
                if c == b'\x1b':
                    seq = b'\x1b'
                    while True:
                        next_c = r.recv(1)
                        if not next_c:
                            break
                        seq += next_c
                        if next_c in b'ABCDEFGHJKSTfhlmnsu':
                            break

                    # Parse cursor position commands
                    if b'H' in seq or b'f' in seq:
                        params = seq[2:-1].decode('ascii').split(';')
                        if len(params) == 2:
                            row, col = map(int, params)
                            current_pos = [row, col]
                    elif b'G' in seq:
                        col = int(seq[2:-1].decode('ascii'))
                        current_pos[1] = col
                    elif b'd' in seq:
                        row = int(seq[2:-1].decode('ascii'))
                        current_pos[0] = row

                # Regular character - track if on line 8
                else:
                    if current_pos[0] == 8:
                        pos = current_pos[1]
                        char = c.decode('latin1')
                        if pos not in line8:
                            line8[pos] = []
                        line8[pos].append((char, current_time))
                        current_pos[1] += 1

            except EOFError:
                break

    finally:
        r.close()

    return line8

def reconstruct_message(line8_chars):
    # Sort positions
    positions = sorted(line8_chars.keys())

    # For each position, look at the characters written there
    message = ""
    for pos in positions:
        chars = line8_chars[pos]
        if chars:
            # Take the last character written at this position
            message += chars[-1][0]

    return message

def main():
    # Collect data from multiple connections
    messages = []
    for _ in range(5):
        line8 = analyze_line8()
        msg = reconstruct_message(line8)
        messages.append(msg)
        print(f"Message attempt: {msg}")
        time.sleep(1)

    # Find patterns in the messages
    common_chars = {}
    for msg in messages:
        for pos, char in enumerate(msg):
            if pos not in common_chars:
                common_chars[pos] = {}
            if char not in common_chars[pos]:
                common_chars[pos][char] = 0
            common_chars[pos][char] += 1

    # Build most common character at each position
    final_msg = ""
    for pos in sorted(common_chars.keys()):
        chars = common_chars[pos]
        most_common = max(chars.items(), key=lambda x: x[1])
        final_msg += most_common[0]

    print(f"\nReconstructed message: {final_msg}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from pwn import *
import re
import time

def decode_terminal():
    r = remote('misc.chal.csaw.io', 3535)

    # Track screen contents and cursor position
    screen = {}  # (row, col) -> char
    hidden_text = []  # list of (char, row, col, timestamp)
    cursor = [1, 1]  # [row, col]

    # Regex for ANSI sequences
    ansi_re = re.compile(rb'\x1b\[([0-9;]*)([A-Za-z])')

    try:
        buffer = b''
        start_time = time.time()

        while True:
            try:
                c = r.recv(1)
                if not c:
                    break

                current_time = time.time() - start_time

                if c == b'\x1b':
                    buffer = c
                    while True:
                        next_c = r.recv(1)
                        if not next_c:
                            break
                        buffer += next_c
                        if next_c in b'ABCDEFGHJKSTfhlmnsu':
                            break

                    # Parse ANSI sequence
                    match = ansi_re.match(buffer)
                    if match:
                        params = match.group(1).decode('ascii')
                        command = match.group(2).decode('ascii')

                        # Handle cursor positioning
                        if command in 'Hf':  # ESC[row;colH or ESC[row;colf
                            if params:
                                parts = params.split(';')
                                if len(parts) == 2:
                                    cursor = [int(parts[0]), int(parts[1])]
                        elif command == 'G':  # ESC[colG
                            if params:
                                cursor[1] = int(params)
                        elif command == 'd':  # ESC[rowd
                            if params:
                                cursor[0] = int(params)

                    buffer = b''
                else:
                    # Regular character - track its position
                    char = c.decode('latin1')
                    pos = tuple(cursor)

                    # Store the character
                    if pos[0] == 8:  # We're interested in line 8
                        # Log if it's being overwritten
                        if pos in screen:
                            hidden_text.append((screen[pos], pos[0], pos[1], current_time))
                        screen[pos] = char
                        hidden_text.append((char, pos[0], pos[1], current_time))

                    cursor[1] += 1  # Move cursor right

            except EOFError:
                break

    finally:
        r.close()

    return screen, hidden_text

def analyze_multiple_runs(num_runs=5):
    all_screens = []
    all_hidden = []

    for i in range(num_runs):
        print(f"Run {i+1}/{num_runs}")
        screen, hidden = decode_terminal()
        all_screens.append(screen)
        all_hidden.append(hidden)
        time.sleep(1)

    # Analyze line 8 across runs
    line8_chars = {}
    for screen in all_screens:
        for (row, col), char in screen.items():
            if row == 8:
                if col not in line8_chars:
                    line8_chars[col] = {}
                if char not in line8_chars[col]:
                    line8_chars[col][char] = 0
                line8_chars[col][char] += 1

    # Build message from most common characters
    message = ""
    for col in sorted(line8_chars.keys()):
        chars = line8_chars[col]
        most_common = max(chars.items(), key=lambda x: x[1])
        message += most_common[0]

    print("\nReconstructed message:", message)

    # Analyze timing patterns in hidden text
    for i, hidden in enumerate(all_hidden):
        print(f"\nRun {i+1} hidden text sequence:")
        filtered = [h for h in hidden if h[1] == 8]  # Only line 8
        if filtered:
            sequence = ""
            for char, row, col, ts in sorted(filtered, key=lambda x: x[3]):
                sequence += char
            print(sequence)

def main():
    analyze_multiple_runs()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from pwn import *
import re
import time

def connect_and_record():
    r = remote('misc.chal.csaw.io', 3535)
    screen = {}
    cursor = [1, 1]

    try:
        buffer = b''
        all_bytes = b''

        while True:
            try:
                c = r.recv(1)
                if not c:
                    break

                all_bytes += c

                if c == b'\x1b':
                    buffer = c
                    while True:
                        next_c = r.recv(1)
                        if not next_c:
                            break
                        buffer += next_c
                        all_bytes += next_c
                        if next_c in b'ABCDEFGHJKSTfhlmnsu':
                            break

                    # Parse cursor position
                    if b'H' in buffer or b'f' in buffer:
                        match = re.match(rb'\x1b\[(\d+);(\d+)[Hf]', buffer)
                        if match:
                            cursor = [int(match.group(1)), int(match.group(2))]
                    elif b'G' in buffer:
                        match = re.match(rb'\x1b\[(\d+)G', buffer)
                        if match:
                            cursor[1] = int(match.group(1))
                    elif b'd' in buffer:
                        match = re.match(rb'\x1b\[(\d+)d', buffer)
                        if match:
                            cursor[0] = int(match.group(1))

                    buffer = b''
                else:
                    # Regular character
                    char = c.decode('latin1')
                    pos = tuple(cursor)
                    screen[pos] = char
                    cursor[1] += 1

                # Look for potential flag patterns
                text = all_bytes.decode('latin1')
                flag_match = re.search(r'flag{[^}]+}', text)
                if flag_match:
                    return flag_match.group(0)

            except EOFError:
                break

    finally:
        r.close()

    return None

def main():
    print("Searching for flag...")
    for i in range(10):
        flag = connect_and_record()
        if flag:
            print(f"Found flag: {flag}")
            return
        print(f"Attempt {i+1} completed, no flag found yet")
        time.sleep(1)

    print("No flag found after 10 attempts")

if __name__ == "__main__":
    main()
